def minMergesForPalindrome(nums):
    i, j = 0, len(nums) - 1
    a, b = nums[i], nums[j]
    ops = 0
    while i < j:
        if a == b:
            i += 1
            j -= 1
            if i < j:
                a, b = nums[i], nums[j]
        elif a < b:
            i += 1
            a += nums[i]
            ops += 1
        else:
            j -= 1
            b += nums[j]
            ops += 1
    return ops
